import { EBaseApiTags } from 'shared/typings';

import { enhancedApi } from './codegen.api';

export const sourceApi = enhancedApi.enhanceEndpoints({
	addTagTypes: [EBaseApiTags.SOURCES],
	endpoints: {
		sourcesList: {
			providesTags: [EBaseApiTags.SOURCES],
		},
		sourcesCreate: {
			invalidatesTags: (_, error) => (error ? [] : [EBaseApiTags.SOURCES]),
		},
		sourcesRetrieve: {
			providesTags: [EBaseApiTags.SOURCES],
		},
		sourcesUpdate: {
			invalidatesTags: (_, error) => (error ? [] : [EBaseApiTags.SOURCES]),
		},
		sourcesPartialUpdate: {
			invalidatesTags: (_, error) => (error ? [] : [EBaseApiTags.SOURCES]),
		},
		sourcesDestroy: {
			invalidatesTags: (_, error) => (error ? [] : [EBaseApiTags.SOURCES]),
		},
	},
});

export const {
	useSourcesListQuery,
	useSourcesCreateMutation,
	useSourcesRetrieveQuery,
	useSourcesUpdateMutation,
	useSourcesPartialUpdateMutation,
	useSourcesDestroyMutation,
} = sourceApi;
